{"n": 7550, "src": "Oslava se koná v noci na městském chodníku.", "en": "The celebration happens at night on a city pavement.", "lk_supplied": "at", "topic": "Prepositions of place/time", "level": "A1", "person": null, "number": null, "perfective_present": null}
{"n": 7551, "src": "Zlato, prý obvykle slaví uvnitř. Dnes večer slaví venku.", "en": "Bestie, she said she usually celebrates inside. Tonight she is celebrating outside.", "lk_supplied": "is celebrating", "topic": "Present Continuous or Simple", "level": "A2", "person": null, "number": null, "perfective_present": true}
{"n": 7552, "src": "Ty držíš své dvě karty jako profík, fakt působivé.", "en": "You hold your two cards like a pro, low-key impressive.", "lk_supplied": "hold", "topic": "Present Simple", "level": "A1", "person": "2sg", "number": "sg", "perfective_present": false}
{"n": 7553, "src": "Nikdo by neměl teď sahat na jeho karty, jinak je všechno zničené!", "en": "Nobody should touch his cards now, or everything is ruined!", "lk_supplied": "should", "topic": "Modal verb SHOULD", "level": "A2", "person": "3sg", "number": "sg", "perfective_present": false}
